import pandas as pd
import json
import logging
from pathlib import Path

# --- Configuration ---
ROOT_DIR = Path(__file__).resolve().parent.parent
DATA_DIR = ROOT_DIR / 'data'

# The tables generated by your JSONLWriter
TABLES = [
    'user', 
    'repository', 
    'pull_request', 
    'pr_commits', 
    'pr_commit_details', 
    'pr_comments', 
    'pr_timeline', 
    'pr_reviews', 
    'related_issue', 
    'issue'
]

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)

def load_jsonl_to_df(file_path):
    """Reads a JSONL file and returns a pandas DataFrame."""
    if not file_path.exists():
        return pd.DataFrame()
    
    records = []
    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            if line.strip():
                records.append(json.loads(line))
    return pd.DataFrame(records)

def main():
    if not DATA_DIR.exists():
        logger.error(f"❌ Data directory not found at {DATA_DIR}")
        return

    logger.info("🚀 Starting JSONL to CSV merging process...")

    for table in TABLES:
        part1_file = DATA_DIR / f"{table}_part1.jsonl"
        part2_file = DATA_DIR / f"{table}_part2.jsonl"
        
        # 1. Load Data
        df1 = load_jsonl_to_df(part1_file)
        df2 = load_jsonl_to_df(part2_file)
        
        combined_df = pd.concat([df1, df2], ignore_index=True)
        
        if combined_df.empty:
            logger.warning(f"⚠️ No data found for {table}. Skipping.")
            continue
            
        initial_len = len(combined_df)
        
        # 2. Deduplicate based on Entity type
        # Users and Repositories have unique 'id' fields. 
        if table in ['user', 'repository', 'pull_request', 'issue', 'pr_comments', 'pr_reviews']:
            combined_df.drop_duplicates(subset=['id'], keep='first', inplace=True)
            
        # Commits are unique per PR + SHA
        elif table == 'pr_commits':
            combined_df.drop_duplicates(subset=['pr_id', 'sha'], keep='first', inplace=True)
            
        # Commit details are unique per PR + SHA + Filename
        elif table == 'pr_commit_details':
            combined_df.drop_duplicates(subset=['pr_id', 'sha', 'filename'], keep='first', inplace=True)
            
        # Junction tables or timeline events without strict IDs
        else:
            # Drop completely identical rows (e.g., related_issue, pr_timeline)
            # For timelines, we convert dicts/lists to strings temporarily if necessary, 
            # but your schema flattens most things so a standard drop_duplicates works.
            combined_df.drop_duplicates(inplace=True)

        final_len = len(combined_df)
        dropped_count = initial_len - final_len
        
        # 3. Export to CSV
        output_file = DATA_DIR / f"{table}_combined.csv"
        
        # Escape formulas just in case PR bodies start with '=' to avoid CSV injection
        combined_df.to_csv(output_file, index=False, encoding='utf-8', escapechar='\\')
        
        logger.info(f"✅ Processed {table}:")
        logger.info(f"   -> Part 1 rows: {len(df1)}")
        logger.info(f"   -> Part 2 rows: {len(df2)}")
        if dropped_count > 0:
            logger.info(f"   -> Removed {dropped_count} duplicate rows.")
        logger.info(f"   -> Saved {final_len} rows to {output_file.name}")

    logger.info("🎉 All files parsed and merged successfully.")

if __name__ == "__main__":
    main()